assertion:
param($Connections)
$policy = Invoke-MgGraphRequest -Method GET -Uri 'https://graph.microsoft.com/v1.0/policies/identitySecurityDefaultsEnforcementPolicy'
$caPolicies = Invoke-MgGraphRequest -Method GET -Uri 'https://graph.microsoft.com/v1.0/identity/conditionalAccess/policies'
$caEnabled = ($caPolicies.value | Where-Object { $_.state -eq 'enabled' }).Count -gt 0
$sdEnabled = $policy.isEnabled
if ($caEnabled -and $sdEnabled) {
  return @{ Pass = $false; Detail = 'Security Defaults is ENABLED while Conditional Access policies are active — this causes conflicts.'; Evidence = $policy }
}
return @{ Pass = $true; Detail = 'Security Defaults is correctly disabled while CA policies are in use.'; Evidence = $policy }

param($Connections)
$groups = Invoke-MgGraphRequest -Method GET -Uri 'https://graph.microsoft.com/v1.0/groups?$filter=groupTypes/any(c:c+eq+''Unified'')&$select=id,displayName,visibility'
$publicGroups = $groups.value | Where-Object { $_.visibility -eq 'Public' }
if ($publicGroups.Count -gt 0) {
  return @{ Pass = $false; Detail = "$($publicGroups.Count) public Microsoft 365 group(s) found. Review and convert to Private where appropriate."; Evidence = $publicGroups }
}
return @{ Pass = $true; Detail = 'No unmanaged public Microsoft 365 groups found.'; Evidence = @() }

param($Connections)
$domains = Invoke-MgGraphRequest -Method GET -Uri 'https://graph.microsoft.com/v1.0/domains'
$expiring = $domains.value | Where-Object { $_.passwordValidityPeriodInDays -ne 2147483647 -and $_.passwordValidityPeriodInDays -ne $null }
if ($expiring.Count -gt 0) {
  return @{ Pass = $false; Detail = "$($expiring.Count) domain(s) have password expiration configured. Set to 'Never Expire'."; Evidence = $expiring }
}
return @{ Pass = $true; Detail = 'All domains are configured with passwords set to never expire.'; Evidence = $domains.value }

param($Connections)
$roles = Invoke-MgGraphRequest -Method GET -Uri 'https://graph.microsoft.com/v1.0/directoryRoles'
$adminRole = $roles.value | Where-Object { $_.displayName -eq 'Global Administrator' }
if (-not $adminRole) {
  return @{ Pass = $false; Detail = 'Could not locate Global Administrator role.'; Evidence = $null }
}
$members = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/directoryRoles/$($adminRole.id)/members"
$evidence = @{ RoleId = $adminRole.id; MemberCount = $members.value.Count; Members = $members.value | Select-Object id, displayName, userPrincipalName }
return @{ Pass = $true; Detail = "$($members.value.Count) Global Admin(s) found. Verify MFA registration via Entra ID > Users > MFA per-user or via CA policy coverage."; Evidence = $evidence }
